use std::{fs,path::Path,collections::BTreeMap,fmt::Write};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-sdk-paired-control";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-sdk-paired-control";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){let r=Path::new(R);let d=Path::new(D);let a=read(r.join("analysis.json"));assert_eq!(a["SDK_requests"],3126);assert_eq!(a["independent_gnark_exports"],168);assert_eq!(a["next_prior_count"],7177);let pins=read(r.join("capture-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");let inventory=read(r.join("proof-inventory.json"));assert_eq!(inventory.as_object().unwrap().len(),336);for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let paired=&a["cases"]["paired-w16"];let fresh=&a["cases"]["fresh-w16"];let paired_cross=paired["block_bound_crossings"].as_u64().unwrap()+paired["repetition_median_bound_crossings"].as_u64().unwrap();let fresh_cross=fresh["block_bound_crossings"].as_u64().unwrap()+fresh["repetition_median_bound_crossings"].as_u64().unwrap();let conclusion=if paired_cross>0{"Shared-context identical controls also cross the declared calibration bounds at16workers. This method is not established as stable by this trial."}else if fresh_cross>0{"Shared-context identical controls stay within the declared bounds at16workers here, while the matched fresh-process controls cross them. This supports evaluating a separately frozen shared-context comparison; it does not establish universal stability or identify the source of the difference."}else{"Neither context crosses the declared bounds at16workers in this trial. The earlier instability is not reproduced here; that does not establish a cause or rescue earlier qualifications."};let audit=json!({"status":"matched neutral SDK context diagnostic complete","conclusion":conclusion,"SDK_requests":3126,"timed_requests":2856,"priming_requests":270,"processes":90,"stages":168,"independent_gnark_exports":168,"proof_public_members":336,"next_prior_count":7177,"production_sources_checked_unchanged":170,"all8accepted_libraries_reused":true,"new_driver_not_historical_executable":true,"no_new_core_field_build_or_test_claim":true,"closing_pins_checked":pins.as_object().unwrap().len(),"new_cycle_profiles":0,"all_worker_receipts_unchanged":true,"candidate_compared":false,"previous_candidate_screen_rescued":false,"adopted":false,"goal_achieved":false,"next_action":if paired_cross>0{"Keep positive fusion candidates unchanged/unadopted. Shared-context nulls also vary; do not reroll or declare a robust comparison. Use retained per-stage/time/resource data to constrain future measurement designs, and return optimization effort to actual request-critical arithmetic; no generic wait/pool/affinity sweep or old-gate waiver."}else{"Keep previous candidate qualification failed and positive source retained. If future comparisons use within-process pairing, freeze a separate real candidate/source protocol with the same state and independent proof checks; current null data neither adopts it nor proves universal stability. Preserve the full all-eight10x objective and focus substantive changes on actual critical arithmetic."}});save(r.join("closeout.json"),&audit);
 let mut md=format!("# Matched SDK timing contexts\n\n{conclusion} No candidate is compared, no optimization is adopted, and the preceding [positive fusion signal and failed qualification](../2026-10-27-poseidon-direct-dot/README.md) remain unchanged.\n\nNeutral labels A/B invoke the same complete `sdk.prove` path from the exact eight accepted libraries. A newly linked diagnostic driver runs either seven paired A/B blocks in one process or one neutral stage in each fresh process. The paired case retains one key mapping, SDK object, heap and Rayon pool. Its worker TIDs and allowed CPU masks agree before/after all stages. The fresh case uses the same driver and libraries, with new process/key/pool lifetimes. The driver is not the historical accepted executable, and its absolute timings do not replace accepted latency qualification.\n\n## Matched observations\n\nRyzen9950X; primary1x2;16workers on CPUs0–15 or32workers on0–31. Three repetitions, seven blocks and two neutral labels per context/worker count. Each stage has17 timed verified SDK requests. Both modes allocate identical diagnostic buffer capacities before capture. Every process has exactly three initial primes; paired stages have no intermediate primes. Worker order, context order and label order alternate by the frozen protocol.\n\n|Context/workers|Median stage ms|B/A geometric|B/A median|B/A min–max|Block crossings /21|Repetition-median crossings /3|CPU ms/request|Maximum lifetime RSS MiB|\n|---|---:|---:|---:|---:|---:|---:|---:|---:|\n");
 for name in ["paired-w16","fresh-w16","paired-w32","fresh-w32"]{let c=&a["cases"][name];writeln!(md,"|{name}|{:.6}|{:.6}|{:.6}|{:.6}–{:.6}|{}|{}|{:.3}|{:.2}|",c["median_stage_ms"].as_f64().unwrap(),c["ratio_geometric_mean"].as_f64().unwrap(),c["ratio_stats"]["median"].as_f64().unwrap(),c["ratio_stats"]["min"].as_f64().unwrap(),c["ratio_stats"]["max"].as_f64().unwrap(),c["block_bound_crossings"],c["repetition_median_bound_crossings"],c["median_CPU_ms_per_request"].as_f64().unwrap(),c["maximum_lifetime_RSS_mib"].as_f64().unwrap()).unwrap();}
 md.push_str("\nA crossing means a block B/A ratio outside factor1.05, or a repetition's median of seven ratios outside factor1.03. These are descriptive null checks using the previous bounds, not an optimization acceptance gate. All 84 block ratios, per-repetition medians/geometric means, stage samples, first/last-five medians, MAD/ranges, CPU/faults/switches and process RSS remain in [analysis](artifacts/analysis.json), [rows](artifacts/rows.json) and [process receipts](artifacts/processes.json). There are no retries, exclusions or threshold changes. Ratios compare identical code; neither their sign nor their size is an optimization gain.\n\nThe methods jointly differ in process/ASLR, key and pool lifetime, warm age, heap history, and whether independent verification occurs between measured stages or after a group. This comparison does not isolate any one of those causes. Fixed output/sample buffers match capacities, but the custom driver and repeated stage boundaries are still diagnostic context. No absence of drift here establishes universal stability. Any bound crossing remains evidence of neutral variation in this protocol, not proof about an earlier untraced run. Prior scheduling traces associated most runnable switches with `sched_yield`; this trial does not repeat them or establish external preemption.\n\n## Timing and proof validation\n\nEach request timer includes witness construction, fresh blinded proving, self-verification and serialization. Sample recording and previous-result ownership updates follow the elapsed read, as in the standard SDK consumer. Stage resource snapshots bracket the loops. After a stage ends, the final proof/public bytes are copied into buffers allocated before capture. No proof file, JSON or standard output is written until all stages in that process finish. Worker broadcasts occur before priming and after all captures. No new pool, individual worker pinning, proof cache, arithmetic path, table, plan, memory policy or production source is introduced.\n\nThe six paired processes produce84 stage exports over1,446 SDK calls. The84 fresh processes produce84 exports over1,680 calls. Total **3,126 SDK calls**, including **2,856 timed requests and270 primes**, across90processes and168stages. All168 exported164-byte proofs pass independent Gnark verification, fixed public-input hash checks and fresh identity checks against the complete prior7,009-proof ledger and one another. All336proof/public members are retained and hash checked. The next ledger count is **7,177**; internal primes are not counted as exported identities.\n\nThe exact accepted core/field libraries retain their inherited tests and proof qualification; no new core/field build or test run is claimed. The newly linked driver itself is validated through these full verified SDK calls. All worker receipts preserve the expected worker indices/TIDs/allowed masks and a single SDK object. No helper, compiler, hash, archive or independent verifier overlaps a timed process. Helpers compile before captures and analysis begins after all captures. Closing checks rehash all pins and production files.\n\n## Scope\n\nHost/cgroup/CPU-policy snapshots are outside capture; unavailable fields are explicit and do not establish absence of limits or throttling. CPU time includes scheduling. RSS is a process lifetime maximum including load, primes, SDK and diagnostic buffers; it is not minimum RAM. No new cycle or scheduler profile is collected. Production170sources and exactacceptedSDK remain unchanged. No candidate is qualified or adopted and no prior failure is waived.\n\nThe [last complete all-shape SDK matrix](../2026-10-26-pairing-x-chain-sdk/README.md) retains all supplied M5 CPU/Metal comparisons. This diagnostic only measures primary1x2 and does not add all-shape qualification. The original all-eightCPU10× objective remains active and unmet. No AWS/Aeglos, phone, TEE, giant-circuit, swap, minimum-RAM, memory-pressure, concurrent-prover or throughput qualification is added.\n\n");let b=read(r.join("native/control/artifacts.json"));writeln!(md,"Diagnostic executable: `{}`; SHA-256 `{}`.\n",b["binary"].as_str().unwrap(),b["binary_sha256"].as_str().unwrap()).unwrap();md.push_str("[Design](artifacts/design.md), [source audit](artifacts/source-audit.json), [frozen capture plan](artifacts/capture-plan.json), [proof inventory](artifacts/proof-inventory.json), [artifact hashes](artifact-index.json).\n");fs::create_dir_all(d).unwrap();fs::write(d.join("README.md"),md).unwrap();fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",r.join("accepted-source-manifest.json")).unwrap();let mut index=BTreeMap::new();archive(r,r,&d.join("artifacts"),&mut index);for(rel,h)in &index{assert_eq!(&hash(d.join("artifacts").join(rel)),h);}for(p,h)in inventory.as_object().unwrap(){let rel=Path::new(p).strip_prefix(r).unwrap();assert_eq!(hash(d.join("artifacts").join(rel)),h.as_str().unwrap());}save(d.join("artifact-index.json"),&json!(index));println!("{}artifact hashes/336proofmembers checked;3126SDK168Gnark;prior7177",index.len());}
fn archive(root:&Path,here:&Path,dest:&Path,index:&mut BTreeMap<String,String>){let mut paths:Vec<_>=fs::read_dir(here).unwrap().map(|e|e.unwrap().path()).collect();paths.sort();for p in paths{let rel=p.strip_prefix(root).unwrap();if p.is_dir(){archive(root,&p,dest,index);continue;}if !["json","jsonl","rs","md","txt","log","proof","public"].iter().any(|x|p.extension().is_some_and(|e|e==*x)){continue;}let q=dest.join(rel);fs::create_dir_all(q.parent().unwrap()).unwrap();fs::copy(&p,&q).unwrap();let h=hash(&q);assert_eq!(h,hash(&p));index.insert(rel.display().to_string(),h);}}
